contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= depositAmount);

        c.depositsCount(); if (__ESBMC_reverted()) return;
        c.owner(); if (__ESBMC_reverted()) return;

        require(depositAmount > 0);
        require(address(this).balance >= depositAmount);

        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;
        uint beforeCallerBalance = address(this).balance;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;
        uint afterCallerBalance = address(this).balance;

        assert(
            afterCount == beforeCount &&
            (
                (reverted && afterBalance == beforeBalance && afterCallerBalance == beforeCallerBalance) ||
                (!reverted && afterBalance == 0 && afterCallerBalance == beforeCallerBalance + beforeBalance)
            )
        );
    }

    receive() external payable {}
}

