pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 depositAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.depositsCount() {} catch { return; }
        try c.owner() {} catch { return; }
        vm.assume(depositAmount > 0);
        vm.assume(address(this).balance >= depositAmount);
        uint256 beforeCount;
        try c.depositsCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        uint beforeBalance = address(c).balance;
        uint beforeCallerBalance = address(this).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterCount;
        try c.depositsCount() returns (uint256 __r) { afterCount = __r; } catch { return; }
        uint afterBalance = address(c).balance;
        uint afterCallerBalance = address(this).balance;
        assertTrue(afterCount == beforeCount &&
            (
                (reverted && afterBalance == beforeBalance && afterCallerBalance == beforeCallerBalance) ||
                (!reverted && afterBalance == 0 && afterCallerBalance == beforeCallerBalance + beforeBalance)
            ));
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
